  if(action==='enter'){const id=el.dataset.dungeon??selectedDungeon;if(id==='qinglan'){openSheet('历练准备',routePreparation(state));return;}enter(id);return;}
  const isAlchemyResult=action==='claim-production'&&el.dataset.kind==='alchemy'&&!!el.closest('[aria-label="炼丹结果"]');
  const selectedQty=action==='market-sell'?Number(el.closest('.card').querySelector('[data-market-qty]').value):['sell','consume'].includes(action)&&el.closest('.bag-detail')?Number(el.closest('.bag-detail').querySelector('[data-bag-qty]')?.value??1):action==='brew'?Number(el.closest('.card')?.querySelector('[data-brew-qty]')?.value??1):el.dataset.qty===undefined?undefined:Number(el.dataset.qty);
  const succeeded=act(action,{day:Number(el.dataset.day),slot:el.dataset.slot,dungeonId:el.dataset.dungeon,crop:el.dataset.crop,seed:el.dataset.seed??document.querySelector('select[data-seed-for="'+el.dataset.crop+'"]')?.value,soil:el.dataset.soil,kind:el.dataset.kind,item:el.dataset.item,index:el.dataset.index===undefined?undefined:Number(el.dataset.index),id:el.dataset.id,qty:selectedQty,amount:Number(document.querySelector('#amount')?.value)});
  if(succeeded&&isAlchemyResult){const remaining=Object.values(state.production.pills).reduce((a,n)=>a+n,0)+Object.values(state.production.refunds).reduce((a,n)=>a+n,0);if(!remaining)document.querySelector('.modal')?.remove();else{const panel=document.querySelector('[aria-label="炼丹结果"]');if(panel){let status=panel.querySelector('.alchemy-claim-status');if(!status){status=document.createElement('p');status.className='alchemy-claim-status';panel.append(status);}status.textContent='背包空间不足，剩余'+remaining+'份成品或材料保留在丹房，整理后可继续领取。';}}}
  if(succeeded && ['plant','plant-all','harvest','stop-plot','soil','expand-plot','equip','unequip'].includes(action))document.querySelector('.modal')?.remove();
  if(succeeded && action==='expand-plot'){farmPage=Math.floor((state.plots.length-1)/4);page='farm';render();}
